package org.cttelsamicsterrassa.data.core.application.player.delete;
import org.albertsanso.commons.command.*; import org.cttelsamicsterrassa.data.core.domain.player.repository.FederatedPlayerRepository; import javax.inject.*;
@Named public class DeleteFederatedPlayerCommandHandler extends DomainCommandHandler<DeleteFederatedPlayerCommand>{private final FederatedPlayerRepository r;@Inject public DeleteFederatedPlayerCommandHandler(FederatedPlayerRepository r){this.r=r;}public DomainCommandResponse handle(DeleteFederatedPlayerCommand c){return r.findFederatedPlayerById(c.getFederatedPlayerId()).map(p->{p.delete();r.deleteFederatedPlayerById(c.getFederatedPlayerId());return DomainCommandResponse.successResponse("FederatedPlayer deleted successfully: "+c.getFederatedPlayerId());}).orElseGet(()->DomainCommandResponse.successResponse("FederatedPlayer not found: "+c.getFederatedPlayerId()));}}
